package com.ibm.il.dse.operations.common;

import com.ibm.dse.base.CCOperationStep;
import com.ibm.dse.base.Context;

/**
 * Shared utility opStep. Validates that required context fields are present and non-blank.
 *
 * XML attributes:
 *   RequiredFields - comma-separated list of field names that must be present in context
 *
 * Returns:
 *   0 - all required fields are present and non-blank
 *   1 - one or more required fields are missing or blank
 */
public class ValidateInputFields extends CCOperationStep {

    private String requiredFields = "";

    public void setRequiredFields(String requiredFields) {
        this.requiredFields = requiredFields;
    }

    @Override
    public int execute() throws Exception {
        Context ctx = getContext();
        if (requiredFields == null || requiredFields.isBlank()) return 0;

        for (String field : requiredFields.split(",")) {
            String name  = field.trim();
            Object value = ctx.getValueAt(name);
            if (value == null || String.valueOf(value).isBlank()) {
                ctx.setValueAt("ValidationFailedField", name);
                return 1;
            }
        }
        return 0;
    }
}

package com.ibm.il.dse.operations.internet.db;

import com.ibm.dse.base.CCOperationStep;
import com.ibm.dse.base.Context;

import java.math.BigDecimal;
import java.sql.CallableStatement;
import java.sql.Connection;
import java.sql.Types;

/**
 * Validates that a transfer does not exceed account limits.
 * Checks: daily limit, available balance, account eligibility.
 *
 * Context reads: SourceAccount, Amount, Currency, ClientId
 * Context writes: DailyRemaining, DailyLimit (on limit exceeded case)
 *
 * Returns:
 *   0 - transfer is within limits and account is eligible
 *   3 - daily transfer limit would be exceeded
 *   4 - insufficient available funds
 *   5 - source account not eligible for outgoing transfers
 *   8 - database error
 */
public class ValidateTransferLimitsSP extends CCOperationStep {

    private static final String SP_NAME =
        "{call PKG_TRANSFERS.VALIDATE_LIMITS(?,?,?,?,?,?)}";

    private static final int RC_SUCCESS         = 0;
    private static final int RC_LIMIT_EXCEEDED  = 3;
    private static final int RC_INSUFFICIENT    = 4;
    private static final int RC_NOT_ELIGIBLE    = 5;
    private static final int RC_DB_ERROR        = 8;

    @Override
    public int execute() throws Exception {
        Context    ctx           = getContext();
        String     sourceAccount = (String)     ctx.getValueAt("SourceAccount");
        BigDecimal amount        = (BigDecimal) ctx.getValueAt("Amount");
        String     clientId      = (String)     ctx.getValueAt("ClientId");

        Connection conn = ctx.getConnection();
        try (CallableStatement cs = conn.prepareCall(SP_NAME)) {
            cs.setString(    1, sourceAccount);
            cs.setBigDecimal(2, amount);
            cs.setString(    3, clientId);

            cs.registerOutParameter(4, Types.VARCHAR);   // validation result code
            cs.registerOutParameter(5, Types.NUMERIC);   // daily remaining
            cs.registerOutParameter(6, Types.NUMERIC);   // daily limit

            cs.execute();

            String spRc = cs.getString(4);
            switch (spRc) {
                case "LIMIT_EXCEEDED":
                    ctx.setValueAt("DailyRemaining", cs.getBigDecimal(5));
                    ctx.setValueAt("DailyLimit",     cs.getBigDecimal(6));
                    return RC_LIMIT_EXCEEDED;
                case "INSUFFICIENT":
                    return RC_INSUFFICIENT;
                case "NOT_ELIGIBLE":
                    return RC_NOT_ELIGIBLE;
                default:
                    return RC_SUCCESS;
            }
        } catch (Exception e) {
            ctx.setValueAt("DatabaseError", e.getMessage());
            return RC_DB_ERROR;
        }
    }
}

package com.ibm.il.dse.operations.internet.service;

import com.ibm.dse.base.CCOperationStep;
import com.ibm.dse.base.Context;
import com.ibm.il.dse.cc.service.communication.http.HTTPService;

import java.math.BigDecimal;

/**
 * Calls the fraud detection backend service via HTTP.
 * This opStep has a configurable timeout (ServiceTimeout attribute).
 *
 * XML attributes:
 *   ServiceTimeout - milliseconds before onTimeoutDo fires (default 5000)
 *
 * Context reads: SourceAccount, TargetAccount, Amount, Currency, ClientId
 * Context writes: FraudScore (int 0-100), FraudDecision (ALLOW/BLOCK)
 *
 * Returns:
 *   0 - fraud check passed (ALLOW decision)
 *   2 - fraud suspected (BLOCK decision, score >= threshold)
 *  -99 - timeout (handled by onTimeoutDo routing)
 *   8 - service error
 */
public class CallFraudDetection extends CCOperationStep {

    private int serviceTimeout = 5000;

    public void setServiceTimeout(String timeout) {
        this.serviceTimeout = Integer.parseInt(timeout);
    }

    @Override
    public int execute() throws Exception {
        Context    ctx           = getContext();
        String     sourceAccount = (String)     ctx.getValueAt("SourceAccount");
        String     targetAccount = (String)     ctx.getValueAt("TargetAccount");
        BigDecimal amount        = (BigDecimal) ctx.getValueAt("Amount");
        String     clientId      = (String)     ctx.getValueAt("ClientId");

        // Build fraud check request payload
        String requestPayload = buildFraudRequest(clientId, sourceAccount, targetAccount, amount);

        // Call fraud service via HTTPService
        HTTPService httpService = (HTTPService) getService("FraudDetectionService");
        String response;
        try {
            response = httpService.call(requestPayload, serviceTimeout);
        } catch (java.util.concurrent.TimeoutException e) {
            return -99; // timeout -> onTimeoutDo routing
        } catch (Exception e) {
            ctx.setValueAt("ServiceError", e.getMessage());
            return 8;
        }

        // Parse response
        int fraudScore = parseFraudScore(response);
        String decision = parseFraudDecision(response);

        ctx.setValueAt("FraudScore",    fraudScore);
        ctx.setValueAt("FraudDecision", decision);

        // Score >= 70 is considered fraud
        return "BLOCK".equals(decision) ? 2 : 0;
    }

    private String buildFraudRequest(String clientId, String src, String tgt, BigDecimal amt) {
        return "<FraudCheckRequest>"
            + "<ClientId>" + clientId + "</ClientId>"
            + "<SourceAccount>" + src + "</SourceAccount>"
            + "<TargetAccount>" + tgt + "</TargetAccount>"
            + "<Amount>" + amt + "</Amount>"
            + "</FraudCheckRequest>";
    }

    private int parseFraudScore(String response) {
        // Simplified parser for demo
        int start = response.indexOf("<Score>") + 7;
        int end   = response.indexOf("</Score>");
        if (start > 6 && end > start) {
            return Integer.parseInt(response.substring(start, end));
        }
        return 0;
    }

    private String parseFraudDecision(String response) {
        return response.contains("<Decision>BLOCK</Decision>") ? "BLOCK" : "ALLOW";
    }
}

package com.ibm.il.dse.operations.common;

import com.ibm.dse.base.CCOperationStep;
import com.ibm.dse.base.Context;

/**
 * Shared utility opStep. Sets a named context field to a fixed value.
 * Useful for marking flags or states during operation execution.
 *
 * XML attributes:
 *   FieldName  - name of context field to set
 *   FieldValue - value to assign (string)
 *
 * Returns: 0 always
 */
public class SetChannelContext extends CCOperationStep {

    private String fieldName  = null;
    private String fieldValue = null;

    public void setFieldName(String fieldName)   { this.fieldName  = fieldName;  }
    public void setFieldValue(String fieldValue) { this.fieldValue = fieldValue; }

    @Override
    public int execute() throws Exception {
        if (fieldName != null) {
            getContext().setValueAt(fieldName, fieldValue);
        }
        return 0;
    }
}

package com.ibm.il.dse.operations.internet.db;

import com.ibm.dse.base.CCOperationStep;
import com.ibm.dse.base.Context;

import java.math.BigDecimal;
import java.sql.CallableStatement;
import java.sql.Connection;
import java.sql.Types;

/**
 * Executes a funds transfer between two accounts in the core banking database.
 *
 * Context reads: SourceAccount, TargetAccount, Amount, Currency, TransferReference,
 *                SessionToken, FraudScore
 * Context writes: TransferId, TransferStatus, ExecutionDate, ExecutionTime,
 *                 NewSourceBalance
 *
 * Returns:
 *   0 - transfer executed successfully
 *   6 - rejected by core banking (account rules, SWIFT, etc.)
 *   7 - duplicate transfer reference (already processed)
 *   8 - database error
 */
public class ExecuteTransferSP extends CCOperationStep {

    private static final String SP_NAME =
        "{call PKG_TRANSFERS.EXECUTE_TRANSFER(?,?,?,?,?,?,?,?,?,?)}";

    private static final int RC_SUCCESS   = 0;
    private static final int RC_REJECTED  = 6;
    private static final int RC_DUPLICATE = 7;
    private static final int RC_DB_ERROR  = 8;

    @Override
    public int execute() throws Exception {
        Context ctx = getContext();

        String     sourceAccount = (String)     ctx.getValueAt("SourceAccount");
        String     targetAccount = (String)     ctx.getValueAt("TargetAccount");
        BigDecimal amount        = (BigDecimal) ctx.getValueAt("Amount");
        String     currency      = (String)     ctx.getValueAt("Currency");
        String     reference     = (String)     ctx.getValueAt("TransferReference");

        Connection conn = ctx.getConnection();
        try (CallableStatement cs = conn.prepareCall(SP_NAME)) {
            // IN params
            cs.setString(    1, sourceAccount);
            cs.setString(    2, targetAccount);
            cs.setBigDecimal(3, amount);
            cs.setString(    4, currency != null ? currency.trim() : "ILS");
            cs.setString(    5, reference);

            // OUT params
            cs.registerOutParameter(6,  Types.VARCHAR);   // return code
            cs.registerOutParameter(7,  Types.VARCHAR);   // transfer id
            cs.registerOutParameter(8,  Types.VARCHAR);   // transfer status
            cs.registerOutParameter(9,  Types.DATE);      // execution date
            cs.registerOutParameter(10, Types.NUMERIC);   // new source balance

            cs.execute();

            String spRc = cs.getString(6);
            if ("REJECTED".equals(spRc))  return RC_REJECTED;
            if ("DUPLICATE".equals(spRc)) return RC_DUPLICATE;

            ctx.setValueAt("TransferId",       cs.getString(7));
            ctx.setValueAt("TransferStatus",   cs.getString(8));
            ctx.setValueAt("ExecutionDate",    cs.getDate(9));
            ctx.setValueAt("ExecutionTime",    new java.util.Date());
            ctx.setValueAt("NewSourceBalance", cs.getBigDecimal(10));

        } catch (Exception e) {
            ctx.setValueAt("DatabaseError", e.getMessage());
            return RC_DB_ERROR;
        }
        return RC_SUCCESS;
    }
}

package com.ibm.il.dse.operations.common;

import com.ibm.dse.base.CCOperationStep;
import com.ibm.dse.base.Context;

/**
 * Shared utility opStep. Sets ErrorCategory and ErrorNumber in context.
 * Used by virtually every operation for error handling.
 *
 * XML attributes (passed via setter methods):
 *   ErrorCategory - string category code (e.g. "10", "99")
 *   ErrorNumber   - string error number within category (e.g. "0", "4")
 *
 * Returns:
 *   0 - always (mapping always succeeds)
 */
public class MapErrorByValueAlways extends CCOperationStep {

    private String errorCategory = "99";
    private String errorNumber   = "0";

    public void setErrorCategory(String errorCategory) {
        this.errorCategory = errorCategory;
    }

    public void setErrorNumber(String errorNumber) {
        this.errorNumber = errorNumber;
    }

    @Override
    public int execute() throws Exception {
        Context ctx = getContext();
        ctx.setValueAt("ErrorCategory",   errorCategory);
        ctx.setValueAt("ErrorNumber",     errorNumber);
        ctx.setValueAt("ErrorDescription", resolveErrorDescription(errorCategory, errorNumber));
        return 0;
    }

    private String resolveErrorDescription(String category, String number) {
        // Lookup from error message catalog (simplified for demo)
        String key = category + "_" + number;
        switch (key) {
            case "10_2": return "Validation failed: required field missing or invalid";
            case "20_1": return "No data found for the provided criteria";
            case "20_4": return "Account not found";
            case "30_5": return "Access denied: insufficient permissions";
            case "40_3": return "Daily transfer limit exceeded";
            case "40_4": return "Insufficient funds";
            case "40_5": return "Account not eligible for this operation";
            case "50_2": return "Transfer blocked: fraud risk detected";
            case "60_6": return "Core banking system rejected the request";
            case "60_7": return "Transfer already processed";
            case "99_0": return "Technical error: unexpected system failure";
            case "99_8": return "Technical error: database connection failure";
            default:     return "System error (category=" + category + ", number=" + number + ")";
        }
    }
}

package com.ibm.dse.base;

import java.sql.Connection;
import java.util.HashMap;
import java.util.Map;
import java.util.Objects;

/** Demo operation context containing named values and an externally supplied JDBC connection. */
public class Context {
    private final Map<String, Object> values = new HashMap<>();
    private Connection connection;

    public Object getValueAt(String name) {
        return values.get(Objects.requireNonNull(name, "Context field name"));
    }

    public void setValueAt(String name, Object value) {
        values.put(Objects.requireNonNull(name, "Context field name"), value);
    }

    /** The caller owns the connection and its transaction lifecycle. */
    public void setConnection(Connection connection) {
        this.connection = Objects.requireNonNull(connection, "JDBC connection");
    }

    public Connection getConnection() {
        if (connection == null) {
            throw new IllegalStateException("Configure a JDBC connection before executing a database step");
        }
        return connection;
    }
}

package com.ibm.dse.base;

import java.util.HashMap;
import java.util.Map;
import java.util.Objects;

/** Demo step contract with a shared operation context and explicitly registered services. */
public abstract class CCOperationStep {
    private Context context;
    private final Map<String, Object> services = new HashMap<>();

    public abstract int execute() throws Exception;

    public void setContext(Context context) {
        this.context = Objects.requireNonNull(context, "Operation context");
    }

    public Context getContext() {
        if (context == null) {
            throw new IllegalStateException("Configure an operation context before executing a step");
        }
        return context;
    }

    public void setService(String name, Object service) {
        services.put(Objects.requireNonNull(name, "Service name"), Objects.requireNonNull(service, "Service"));
    }

    public Object getService(String name) {
        Object service = services.get(Objects.requireNonNull(name, "Service name"));
        if (service == null) {
            throw new IllegalStateException("Configure the named service before executing a step: " + name);
        }
        return service;
    }
}

package com.ibm.il.dse.cc.format;

import com.ibm.dse.base.Context;
import com.ibm.dse.base.Tag;

/**
 * Boolean field formatter. Maps "true"/"false" XML values to/from context.
 *
 * Attributes:
 *   dataName - the XML element name and context field name
 *   trueValue  - XML string representing true  (default: "true")
 *   falseValue - XML string representing false (default: "false")
 */
public class CCBoolean extends AbstractFormatElement {

    private String dataName;
    private String trueValue  = "true";
    private String falseValue = "false";

    @Override
    public void initializeFrom(Tag tag) {
        this.dataName   = tag.getAttribute("dataName");
        String tv = tag.getAttribute("trueValue");
        if (tv != null) this.trueValue = tv;
        String fv = tag.getAttribute("falseValue");
        if (fv != null) this.falseValue = fv;
    }

    @Override
    public String format(Context ctx) throws Exception {
        Object val = ctx.getValueAt(dataName);
        boolean b = Boolean.TRUE.equals(val) || "true".equalsIgnoreCase(String.valueOf(val));
        return "<" + dataName + ">" + (b ? trueValue : falseValue) + "</" + dataName + ">";
    }

    @Override
    public void unformat(String xml, Context ctx) throws Exception {
        String value = extractElement(xml, dataName);
        ctx.setValueAt(dataName, trueValue.equalsIgnoreCase(value));
    }

    private String extractElement(String xml, String name) { throw new UnsupportedOperationException(); }
}

